mapper.select:
select count(*)
from report
where reporter_id = #{reporterId}
  and target_type = #{targetType}
  and target_id = #{targetId}
  and status = 0

select distinct target_id
from report
where reporter_id = #{reporterId}
  and target_type = #{targetType}
  and status = 0
order by target_id desc

select count(*)
from report
where target_type = #{targetType} and target_id = #{targetId}

select id, target_type, target_id, target_author_id, reporter_id, reason_code, detail, status, created_at
from report
where target_type = #{targetType}
  and target_id = #{targetId}
  and status = 0
  and id != #{exceptId}
order by id asc
